class StdinTests(CliTestCase):
    def test_dash_reads_stdin(self):
        self.assertEqual(run(["balance", "-"], stdin=LEDGER), (0, "1557.50\n", ""))
        self.assertEqual(run(["summary", "-"], stdin=LEDGER)[1].count("\n"), 3)
        self.assertEqual(run(["list", "-"], stdin=LEDGER)[1].count("\n"), 3)
        self.assertEqual(run(["export", "-"], stdin=LEDGER)[1].count("\n"), 4)

    def test_dash_parse_error(self):
        status, out, err = run(["balance", "-"], stdin="\n2024-02-30 x 1\n")
        self.assertEqual((status, out), (1, ""))
        self.assertIn("line 2", err)


class ExitCodeTests(CliTestCase):
    def test_parse_error_exit_1_line_in_stderr_empty_stdout(self):
        bad = self.write("bad.txt", "# c\n2024-03-01 x 1\n\n2024-02-30 x 1\n")
        for cmd in (["balance"], ["summary"], ["list"], ["export"], ["list", "--json"]):
            with self.subTest(cmd):
                argv = [cmd[0], bad] + cmd[1:]
                status, out, err = run(argv)
                self.assertEqual((status, out), (1, ""))
                self.assertIn("line 4", err)

    def test_missing_file_exit_2(self):
        status, out, err = run(["balance", os.path.join(self.dir, "missing.txt")])
        self.assertEqual((status, out), (2, ""))
        self.assertTrue(err)

class SubprocessTests(CliTestCase):
    def _run(self, args, stdin=None):
        env = dict(os.environ, PYTHONPATH=ROOT)
        return subprocess.run(
            [sys.executable, "-m", "pennywise"] + args,
            input=stdin, capture_output=True, text=True, env=env, cwd=self.dir,
        )

    def test_module_balance(self):
        r = self._run(["balance", self.path])
        self.assertEqual((r.returncode, r.stdout, r.stderr), (0, "1557.50\n", ""))

    def test_module_stdin(self):
        r = self._run(["list", "-"], stdin=LEDGER)
        self.assertEqual(r.returncode, 0)
        self.assertIn("2024-03-02 groceries -42.50 weekly shop", r.stdout)

    def test_module_exit_codes(self):
        bad = self.write("bad.txt", "oops\n")
        r = self._run(["balance", bad])
        self.assertEqual((r.returncode, r.stdout), (1, ""))
        self.assertIn("line 1", r.stderr)
        self.assertEqual(self._run(["balance", "nope.txt"]).returncode, 2)
        self.assertEqual(self._run([]).returncode, 2)

    def test_module_undecodable_stdin(self):
        env = dict(os.environ, PYTHONPATH=ROOT)
        r = subprocess.run(
            [sys.executable, "-m", "pennywise", "balance", "-"],
            input=b"\xff\xfe\n", capture_output=True, env=env,
        )
        self.assertEqual((r.returncode, r.stdout), (2, b""))


