"""Command line interface: ``pennywise`` / ``python -m pennywise``."""

import argparse
import csv
import json
import os
import re
import sys

from .ledger import ParseError, format_amount, format_entry, parse, parse_date
from .reports import balance, by_category, by_month, filter_entries

_PROG = "pennywise"
_WHITESPACE = re.compile(r"\s")


class _IOFailure(Exception):
    """A file could not be read or written (exit status 2)."""


def _date_option(text):
    try:
        return parse_date(text)
    except ValueError as exc:
        raise argparse.ArgumentTypeError(str(exc)) from None


def _build_parser():
    parser = argparse.ArgumentParser(
        prog=_PROG, description="Report where the money went, from a plain-text ledger."
    )
    sub = parser.add_subparsers(dest="command", metavar="COMMAND")
    sub.required = True

    p = sub.add_parser("balance", help="print the total of all amounts")
    p.add_argument("file", metavar="FILE", help="ledger file, or - for stdin")
    p.add_argument("--json", action="store_true", help="print JSON")

    p = sub.add_parser("summary", help="print totals per category or month")
    p.add_argument("file", metavar="FILE", help="ledger file, or - for stdin")
    p.add_argument("--by", choices=("category", "month"), default="category")
    p.add_argument("--json", action="store_true", help="print JSON")

    p = sub.add_parser("list", help="print entries, oldest first")
    p.add_argument("file", metavar="FILE", help="ledger file, or - for stdin")
    p.add_argument("--category", help="only this category (case-insensitive)")
    p.add_argument("--since", type=_date_option, metavar="YYYY-MM-DD")
    p.add_argument("--until", type=_date_option, metavar="YYYY-MM-DD")
    p.add_argument("--json", action="store_true", help="print JSON")

    p = sub.add_parser(
        "add",
        help="append an entry to the ledger file",
        usage=f"{_PROG} add [-h] FILE DATE CATEGORY AMOUNT [NOTE]",
        description=(
            "Append an entry to FILE (created if missing) and print the line added. "
            "Everything after FILE is taken as DATE, CATEGORY, AMOUNT and an optional "
            "NOTE, even when a value starts with a dash (for example a note like "
            "'-refund'); the ledger rules then decide whether the entry is valid. "
            "You may also put -- right after FILE to mark the start of the values."
        ),
    )
    p.add_argument("file", metavar="FILE", help="ledger file (created if missing)")
    p.add_argument("values", nargs=argparse.REMAINDER, help=argparse.SUPPRESS)
    p.set_defaults(_usage_error=p.error)

    p = sub.add_parser("export", help="print entries as CSV")
    p.add_argument("file", metavar="FILE", help="ledger file, or - for stdin")
    p.add_argument("--format", choices=("csv",), default="csv")
    return parser


def _read_ledger(path):
    try:
        if path == "-":
            stream = getattr(sys.stdin, "buffer", None)
            raw = stream.read() if stream is not None else sys.stdin.read()
        else:
            with open(path, "rb") as fh:
                raw = fh.read()
        if isinstance(raw, bytes):
            raw = raw.decode("utf-8-sig")
        return raw
    except (OSError, UnicodeDecodeError) as exc:
        name = "standard input" if path == "-" else path
        reason = exc.strerror if isinstance(exc, OSError) and exc.strerror else exc
        raise _IOFailure("cannot read %s: %s" % (name, reason)) from None


def _load(path):
    return parse(_read_ledger(path))


def _by_date(entries):
    return sorted(entries, key=lambda e: e.date)  # stable


def _entry_dict(e):
    return {
        "date": e.date.isoformat(),
        "category": e.category,
        "amount": format_amount(e.amount),
        "note": e.note,
    }


class _Sink:
    def __init__(self):
        self.parts = []

    def write(self, text):
        self.parts.append(text)


def _cmd_balance(args):
    total = format_amount(balance(_load(args.file)))
    return (json.dumps({"balance": total}) if args.json else total) + "\n"


def _cmd_summary(args):
    entries = _load(args.file)
    totals = by_category(entries) if args.by == "category" else by_month(entries)
    shown = {k: format_amount(totals[k]) for k in sorted(totals)}
    if args.json:
        return json.dumps(shown) + "\n"
    return "".join(f"{k}  {v}\n" for k, v in shown.items())


def _cmd_list(args):
    entries = filter_entries(
        _load(args.file), category=args.category, since=args.since, until=args.until
    )
    entries = _by_date(entries)
    if args.json:
        return json.dumps([_entry_dict(e) for e in entries]) + "\n"
    return "".join(format_entry(e) + "\n" for e in entries)


def _cmd_export(args):
    entries = _by_date(_load(args.file))
    out = _Sink()
    writer = csv.writer(out, lineterminator="\n")
    writer.writerow(["date", "category", "amount", "note"])
    for e in entries:
        d = _entry_dict(e)
        writer.writerow([d["date"], d["category"], d["amount"], d["note"]])
    return "".join(out.parts)


def _cmd_add(args):
    values = list(args.values)
    if values and values[0] == "--":  # older argparse keeps the separator
        values.pop(0)
    if not 3 <= len(values) <= 4:
        args._usage_error("expected DATE CATEGORY AMOUNT [NOTE] after FILE")
    date, category, amount, note = values + [""] * (4 - len(values))
    for name, value in (("date", date), ("category", category), ("amount", amount)):
        if not value or _WHITESPACE.search(value):
            raise ParseError(1, "%s must be one word without whitespace" % name)
    if "\n" in note or "\r" in note:
        raise ParseError(1, "note must be a single line")
    line = f"{date} {category} {amount}"
    if note:
        line += f" {note}"
    (entry,) = parse(line)  # validates with the ledger's own rules
    formatted = format_entry(entry)
    try:
        with open(args.file, "a+b") as fh:
            fh.seek(0, 2)
            prefix = b""
            if fh.tell() > 0:
                fh.seek(-1, 2)
                if fh.read(1) != b"\n":
                    prefix = b"\n"
            fh.write(prefix + formatted.encode("utf-8") + b"\n")
    except OSError as exc:
        raise _IOFailure(
            "cannot write %s: %s" % (args.file, exc.strerror or exc)
        ) from None
    return formatted + "\n"


_COMMANDS = {
    "balance": _cmd_balance,
    "summary": _cmd_summary,
    "list": _cmd_list,
    "export": _cmd_export,
    "add": _cmd_add,
}


def _silence_stdout():
    """Point stdout's fd at devnull so the interpreter's exit flush stays quiet."""
    try:
        fd = sys.stdout.fileno()
        devnull = os.open(os.devnull, os.O_WRONLY)
        try:
            os.dup2(devnull, fd)
        finally:
            os.close(devnull)
    except (AttributeError, OSError, ValueError):
        pass


def _emit(text):
    """Write text to stdout; return the exit status."""
    out = sys.stdout
    if out is None:
        print(f"{_PROG}: cannot write output: standard output is closed", file=sys.stderr)
        return 2
    try:
        out.write(text)
        out.flush()
    except BrokenPipeError:
        _silence_stdout()  # the reader stopped early: not an error
        return 0
    except (OSError, ValueError) as exc:
        _silence_stdout()
        reason = exc.strerror if isinstance(exc, OSError) and exc.strerror else exc
        print(f"{_PROG}: cannot write output: {reason}", file=sys.stderr)
        return 2
    return 0


def main(argv=None):
    """Run the CLI; return the exit status (usage errors exit 2 via argparse)."""
    args = _build_parser().parse_args(argv)
    try:
        text = _COMMANDS[args.command](args)
    except ParseError as exc:
        print(f"{_PROG}: {exc}", file=sys.stderr)
        return 1
    except _IOFailure as exc:
        print(f"{_PROG}: {exc}", file=sys.stderr)
        return 2
    # Nothing is printed before this point, so errors leave stdout empty.
    return _emit(text)


if __name__ == "__main__":
    sys.exit(main())

